function c(i){if(!i||typeof i!="string")return{isValid:!1,slug:"",inferredTitle:""};try{const t=new URL(i,"https://leetcode.com");if(!t.hostname.includes("leetcode.com")&&!t.hostname.includes("leetcode.cn")&&!t.hostname.includes("localhost"))return{isValid:!1,slug:"",inferredTitle:""};const s=t.pathname.split("/").filter(Boolean),n=s.indexOf("problems");if(n===-1||n+1>=s.length)return{isValid:!1,slug:"",inferredTitle:""};const o=s[n+1].toLowerCase();let r;const l=s.indexOf("submissions");if(l!==-1&&l+1<s.length){const e=s[l+1];/^\d+$/.test(e)&&(r=e)}const a=o.split("-").map(e=>/^\d+[a-z]+$/i.test(e)?e.slice(0,-3)+"Sum":e.charAt(0).toUpperCase()+e.slice(1)).join(" ");return{isValid:!0,slug:o,inferredTitle:a,submissionId:r}}catch{return{isValid:!1,slug:"",inferredTitle:""}}}export{c as p};
